DROP TABLE IF EXISTS `weight_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weight_product` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `Product_Id` bigint unsigned NOT NULL,
  `price` decimal(10,3) NOT NULL DEFAULT '0.000' COMMENT 'Product weight additional price',
  `weight` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Product weight in grams',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `weight_product_product_id_foreign` (`Product_Id`),
  CONSTRAINT `weight_product_product_id_foreign` FOREIGN KEY (`Product_Id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1086 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

